"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ReactNode, useId, useMemo, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** A day of the week, as a key in the weekly hours. */
export type Weekday = "mon" | "tue" | "wed" | "thu" | "fri" | "sat" | "sun";

/** One span of open time. `start` and `end` are 24-hour "HH:MM" strings, and `end` comes after `start`. */
export interface TimeRange {
  id: string;
  start: string;
  end: string;
}

/** One day's hours. A day that is off keeps its ranges, so switching it back on restores them. */
export interface DayHours {
  enabled: boolean;
  ranges: TimeRange[];
}

/** The hours for a whole week. */
export type WeeklyHours = Record<Weekday, DayHours>;

/** Props for a weekly hours editor. Pass `value` to control it, or `defaultValue` to let it hold its own. */
export interface AvailabilitySchedulerProps {
  value?: WeeklyHours;
  defaultValue?: WeeklyHours;
  onValueChange?: (value: WeeklyHours) => void;
  /** Minutes between the times a person can pick. The default is 30. */
  step?: number;
  /** A BCP 47 locale for the time labels. It defaults to "en-US", so the server and the browser agree. */
  locale?: string;
  className?: string;
}

const WEEKDAYS: { key: Weekday; name: string }[] = [
  { key: "mon", name: "Monday" },
  { key: "tue", name: "Tuesday" },
  { key: "wed", name: "Wednesday" },
  { key: "thu", name: "Thursday" },
  { key: "fri", name: "Friday" },
  { key: "sat", name: "Saturday" },
  { key: "sun", name: "Sunday" },
];

// Damping 41 is 2 × √420, rounded up: critically damped, so rows open without overshoot.
const SETTLE: Transition = { type: "spring", stiffness: 420, damping: 41, mass: 1 };
// Damping 46 is 2 × √520, rounded up: the switch thumb arrives fast and does not wobble.
const THUMB: Transition = { type: "spring", stiffness: 520, damping: 46, mass: 1 };
const FADE: Transition = { duration: 0.15 };
const INSTANT: Transition = { duration: 0 };
const DAY_MINUTES = 24 * 60;

/** Monday to Friday, nine to five. The weekend is off. */
export function defaultWeeklyHours() {
  const workday = (key: Weekday): DayHours => ({ enabled: true, ranges: [{ id: `${key}-0`, start: "09:00", end: "17:00" }] });
  // Each day gets its own object, so editing Saturday never edits Sunday too.
  const off = (): DayHours => ({ enabled: false, ranges: [] });
  return {
    mon: workday("mon"),
    tue: workday("tue"),
    wed: workday("wed"),
    thu: workday("thu"),
    fri: workday("fri"),
    sat: off(),
    sun: off(),
  } satisfies WeeklyHours;
}

const toMinutes = (time: string) => {
  const [hours = 0, minutes = 0] = time.split(":").map(Number);
  return hours * 60 + minutes;
};

const toTime = (minutes: number) =>
  `${String(Math.floor(minutes / 60)).padStart(2, "0")}:${String(minutes % 60).padStart(2, "0")}`;

// Two ranges overlap when each starts before the other ends. Only the ranges in a clash are marked.
const clashingIds = (ranges: TimeRange[]) =>
  new Set(
    ranges
      .filter((a) => ranges.some((b) => a !== b && toMinutes(a.start) < toMinutes(b.end) && toMinutes(b.start) < toMinutes(a.end)))
      .map((range) => range.id),
  );

function PlusGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-4">
      <path d="M3.5 8h9M8 3.5v9" strokeLinecap="round" />
    </svg>
  );
}

function CrossGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-4">
      <path d="m4.5 4.5 7 7M11.5 4.5l-7 7" strokeLinecap="round" />
    </svg>
  );
}

function CopyGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true" className="size-4">
      <rect x="5.5" y="5.5" width="8" height="8" rx="1.75" />
      <path d="M10.5 3.5v-.25A1.25 1.25 0 0 0 9.25 2h-6A1.25 1.25 0 0 0 2 3.25v6a1.25 1.25 0 0 0 1.25 1.25h.25" strokeLinecap="round" />
    </svg>
  );
}

const ICON_BUTTON =
  "group relative grid size-11 shrink-0 cursor-pointer touch-manipulation place-items-center rounded-full text-muted-foreground outline-none hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring aria-disabled:cursor-not-allowed aria-disabled:opacity-40 motion-safe:transition-colors sm:size-9";

// The tip repeats the button's accessible name for sighted users, so it stays hidden from screen readers.
function Tip({ children }: { children: ReactNode }) {
  return (
    <span
      aria-hidden="true"
      className="pointer-events-none absolute bottom-full left-1/2 z-10 mb-1 -translate-x-1/2 whitespace-nowrap rounded-md bg-foreground px-2 py-1 text-xs font-medium text-background opacity-0 motion-safe:transition-opacity motion-safe:duration-150 group-hover:opacity-100 group-focus-visible:opacity-100"
    >
      {children}
    </span>
  );
}

function DaySwitch({ checked, label, onChange, reduceMotion }: { checked: boolean; label: string; onChange: (next: boolean) => void; reduceMotion: boolean }) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      onClick={() => onChange(!checked)}
      className={cn(
        // The pseudo-element grows the hit area to 2.75rem tall without growing the track.
        "relative inline-flex h-6 w-10 shrink-0 cursor-pointer touch-manipulation items-center rounded-full p-0.5 before:absolute before:-inset-x-0.5 before:-inset-y-2.5 outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background motion-safe:transition-colors motion-safe:duration-200",
        checked ? "justify-end bg-primary" : "justify-start bg-muted-foreground/30",
      )}
    >
      {/* The thumb measures only when the switch flips, so a row moving above it never drags it out of its track. */}
      <motion.span layout layoutDependency={checked} transition={reduceMotion ? INSTANT : THUMB} className="size-5 rounded-full bg-background shadow-sm" />
    </button>
  );
}

interface TimeOption {
  value: string;
  label: string;
}

interface TimeSelectProps {
  label: string;
  value: string;
  options: TimeOption[];
  /** The id of the message that explains why the field is invalid. */
  errorId?: string;
  onChange: (next: string) => void;
}

function TimeSelect({ label, value, options, errorId, onChange }: TimeSelectProps) {
  return (
    // The browser's own arrow ignores padding and sits on the border, so the
    // select hides it and draws one inside the same inset as the text.
    <span className="relative flex min-w-0 flex-1 sm:max-w-36">
      <select
        aria-label={label}
        aria-invalid={errorId ? true : undefined}
        aria-describedby={errorId}
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="h-11 w-full min-w-0 cursor-pointer appearance-none rounded-lg border border-border bg-background pl-3 pr-8 text-sm tabular-nums text-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring aria-invalid:border-destructive sm:h-9"
      >
        {options.map((option) => (
          <option key={option.value} value={option.value}>
            {option.label}
          </option>
        ))}
      </select>
      <svg
        aria-hidden="true"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        className="pointer-events-none absolute right-3 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground"
      >
        <path d="M4 6l4 4 4-4" />
      </svg>
    </span>
  );
}

interface CopyPanelProps {
  id: string;
  fromName: string;
  others: { key: Weekday; name: string }[];
  onApply: (targets: Weekday[]) => void;
  onClose: () => void;
  reduceMotion: boolean;
}

// The panel opens inside the row rather than floating over it, so no edge or
// scrolling container can clip it, and Tab reaches it straight after its button.
function CopyPanel({ id, fromName, others, onApply, onClose, reduceMotion }: CopyPanelProps) {
  const [picked, setPicked] = useState<Weekday[]>([]);

  const toggle = (day: Weekday) =>
    setPicked((current) => (current.includes(day) ? current.filter((key) => key !== day) : [...current, day]));

  const apply = () => {
    if (picked.length === 0) return;
    onApply(picked);
    onClose();
  };

  return (
    <motion.div
      id={id}
      initial={reduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
      animate={{ opacity: 1, height: "auto" }}
      exit={reduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
      transition={reduceMotion ? FADE : SETTLE}
      className="col-span-full overflow-hidden"
    >
      <fieldset className="rounded-xl border border-border bg-card p-2">
        <legend className="sr-only">Copy {fromName}&apos;s hours to</legend>
        <p aria-hidden="true" className="px-2 py-1.5 text-xs font-medium text-muted-foreground">
          Copy {fromName}&apos;s hours to
        </p>
        <div className="grid grid-cols-2 gap-x-2 @md:grid-cols-3">
          {others.map((day) => (
            <label key={day.key} className="flex min-h-11 cursor-pointer items-center gap-2 rounded-lg px-2 text-sm hover:bg-muted sm:min-h-9">
              <input
                type="checkbox"
                checked={picked.includes(day.key)}
                onChange={() => toggle(day.key)}
                className="size-4 cursor-pointer accent-primary"
              />
              {day.name}
            </label>
          ))}
        </div>
        <div className="mt-2 flex justify-end gap-2 border-t border-border pt-2">
          <button
            type="button"
            onClick={() => setPicked(others.map((day) => day.key))}
            className="min-h-11 cursor-pointer rounded-lg px-3 text-sm font-medium text-muted-foreground outline-none hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring sm:min-h-9"
          >
            Every day
          </button>
          {/* Not disabled when nothing is picked: a disabled button drops keyboard focus. */}
          <button
            type="button"
            aria-disabled={picked.length === 0 || undefined}
            onClick={apply}
            className="min-h-11 cursor-pointer rounded-lg bg-primary px-3 text-sm font-medium text-primary-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card aria-disabled:cursor-not-allowed aria-disabled:opacity-50 sm:min-h-9"
          >
            Copy hours
          </button>
        </div>
      </fieldset>
    </motion.div>
  );
}

interface DayRowProps {
  day: Weekday;
  name: string;
  hours: DayHours;
  options: TimeOption[];
  /** The start times plus midnight, which only an end can be. */
  endOptions: TimeOption[];
  labelOf: (time: string) => string;
  step: number;
  reduceMotion: boolean;
  onChange: (next: DayHours) => void;
  onCopy: (targets: Weekday[]) => void;
  nextId: () => string;
}

// A value set by the caller may fall between the steps. It stays in the list, so the field never shows blank.
const withCurrent = (options: TimeOption[], value: string, labelOf: (time: string) => string) =>
  options.some((option) => option.value === value)
    ? options
    : [...options, { value, label: labelOf(value) }].sort((a, b) => toMinutes(a.value) - toMinutes(b.value));

function DayRow({ day, name, hours, options, endOptions, labelOf, step, reduceMotion, onChange, onCopy, nextId }: DayRowProps) {
  // A new range starts an hour after the latest end, if the day has room for it.
  const latestEnd = Math.max(...hours.ranges.map((range) => toMinutes(range.end)));
  const nextStart = hours.ranges.length > 0 ? latestEnd + 60 : 9 * 60;
  const canAdd = nextStart + step <= DAY_MINUTES;
  const clashing = hours.enabled ? clashingIds(hours.ranges) : new Set<string>();
  // Ranges re-measure only when this day's own list changes, not when a day above them grows.
  const rangeKey = hours.ranges.map((range) => range.id).join();
  const errorId = useId();
  const copyPanelId = useId();
  const [copyOpen, setCopyOpen] = useState(false);
  const copyButton = useRef<HTMLButtonElement>(null);
  const addButton = useRef<HTMLButtonElement>(null);
  const removeButtons = useRef(new Map<string, HTMLButtonElement>());
  const swap = reduceMotion ? FADE : SETTLE;

  const setEnabled = (enabled: boolean) => {
    // Switching on a day with no hours gives it the usual working day to edit.
    if (enabled && hours.ranges.length === 0) onChange({ enabled, ranges: [{ id: nextId(), start: "09:00", end: "17:00" }] });
    else onChange({ ...hours, enabled });
  };

  const update = (id: string, patch: Partial<TimeRange>) =>
    onChange({ ...hours, ranges: hours.ranges.map((range) => (range.id === id ? { ...range, ...patch } : range)) });

  const add = () => {
    if (!canAdd) return;
    const end = Math.min(nextStart + 60, DAY_MINUTES);
    onChange({ enabled: true, ranges: [...hours.ranges, { id: nextId(), start: toTime(nextStart), end: toTime(end) }] });
  };

  // Removing the last range turns the day off, so an on day always has hours.
  // The pressed button leaves with its range, so focus moves to the next range's
  // remove button, or to the day's add button when none is left.
  const remove = (id: string) => {
    const ranges = hours.ranges.filter((range) => range.id !== id);
    const index = hours.ranges.findIndex((range) => range.id === id);
    const nextFocus = ranges[Math.min(index, ranges.length - 1)]?.id;
    onChange({ enabled: ranges.length > 0, ranges });
    const target = nextFocus ? removeButtons.current.get(nextFocus) : addButton.current;
    target?.focus();
  };

  return (
    // Narrow, the name, the hours and the actions stack. Wide, they share one
    // line. Both keep the order of the markup, so Tab follows what the eye reads.
    <div
      className="grid grid-cols-1 items-start gap-x-4 gap-y-3 py-4 @xl:grid-cols-[10rem_1fr_auto]"
      onKeyDown={(event) => {
        if (event.key !== "Escape" || !copyOpen) return;
        event.stopPropagation();
        setCopyOpen(false);
        copyButton.current?.focus();
      }}
    >
      <div className="flex min-h-11 items-center gap-3 sm:min-h-9">
        <DaySwitch checked={hours.enabled} label={`${name} available`} onChange={setEnabled} reduceMotion={reduceMotion} />
        <span className="text-sm font-medium text-foreground">{name}</span>
      </div>

      <div className="flex min-w-0 flex-col gap-2">
        <AnimatePresence initial={false} mode="popLayout">
          {hours.enabled ? (
            hours.ranges.map((range) => (
              <motion.div
                key={range.id}
                layout={reduceMotion ? false : "position"}
                layoutDependency={rangeKey}
                initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: -6 }}
                animate={{ opacity: 1, y: 0 }}
                exit={reduceMotion ? { opacity: 0 } : { opacity: 0, y: -6 }}
                transition={swap}
                className="flex items-center gap-2"
              >
                <TimeSelect
                  label={`${name} start`}
                  value={range.start}
                  options={withCurrent(options.filter((option) => toMinutes(option.value) < toMinutes(range.end)), range.start, labelOf)}
                  errorId={clashing.has(range.id) ? errorId : undefined}
                  onChange={(start) => update(range.id, { start })}
                />
                <span aria-hidden="true" className="text-sm text-muted-foreground">
                  to
                </span>
                <TimeSelect
                  label={`${name} end`}
                  value={range.end}
                  options={withCurrent(endOptions.filter((option) => toMinutes(option.value) > toMinutes(range.start)), range.end, labelOf)}
                  errorId={clashing.has(range.id) ? errorId : undefined}
                  onChange={(end) => update(range.id, { end })}
                />
                <button
                  ref={(node) => {
                    if (node) removeButtons.current.set(range.id, node);
                    else removeButtons.current.delete(range.id);
                  }}
                  type="button"
                  aria-label={`Remove ${name}'s hours from ${labelOf(range.start)} to ${labelOf(range.end)}`}
                  onClick={() => remove(range.id)}
                  className={ICON_BUTTON}
                >
                  <CrossGlyph />
                  <Tip>Remove</Tip>
                </button>
              </motion.div>
            ))
          ) : (
            <motion.p
              key="off"
              layout={reduceMotion ? false : "position"}
              layoutDependency={hours.enabled}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              transition={FADE}
              className="flex min-h-11 items-center text-sm text-muted-foreground sm:min-h-9"
            >
              Unavailable
            </motion.p>
          )}
        </AnimatePresence>
        {clashing.size > 0 ? (
          <p id={errorId} role="alert" className="text-sm text-destructive">
            These hours overlap. Change one range so they do not.
          </p>
        ) : null}
      </div>

      <div className="flex items-center justify-end gap-1">
        {/* Not disabled when the day is full: a disabled button drops keyboard focus. */}
        <button
          ref={addButton}
          type="button"
          aria-label={`Add hours to ${name}`}
          aria-disabled={!canAdd || undefined}
          onClick={add}
          className={ICON_BUTTON}
        >
          <PlusGlyph />
          <Tip>{canAdd ? "Add hours" : "The day is full"}</Tip>
        </button>
        <button
          ref={copyButton}
          type="button"
          aria-label={`Copy ${name}'s hours to other days`}
          aria-expanded={copyOpen}
          aria-controls={copyPanelId}
          onClick={() => setCopyOpen((open) => !open)}
          className={ICON_BUTTON}
        >
          <CopyGlyph />
          <Tip>Copy hours</Tip>
        </button>
      </div>

      <AnimatePresence initial={false}>
        {copyOpen ? (
          <CopyPanel
            id={copyPanelId}
            fromName={name}
            others={WEEKDAYS.filter((other) => other.key !== day)}
            onApply={onCopy}
            onClose={() => {
              setCopyOpen(false);
              copyButton.current?.focus();
            }}
            reduceMotion={reduceMotion}
          />
        ) : null}
      </AnimatePresence>
    </div>
  );
}

/**
 * Edits the hours someone is available each week. Each day switches on and
 * off, holds one or more time ranges, and can copy its hours to other days.
 */
export function AvailabilityScheduler({ value, defaultValue, onValueChange, step: stepProp = 30, locale = "en-US", className }: AvailabilitySchedulerProps) {
  // Five minutes is the finest step, so the lists stay short enough to scroll.
  const step = Math.max(5, stepProp);
  const [ownValue, setOwnValue] = useState<WeeklyHours>(() => defaultValue ?? defaultWeeklyHours());
  const week = value ?? ownValue;
  const reduceMotion = useReducedMotion() ?? false;
  const counter = useRef(0);
  // A saved week may already hold ids from an earlier visit, so a new id skips any the week uses.
  const nextId = () => {
    const used = new Set(Object.values(week).flatMap((day) => day.ranges.map((range) => range.id)));
    let id = `range-${++counter.current}`;
    while (used.has(id)) id = `range-${++counter.current}`;
    return id;
  };

  // Labels come from Intl in UTC, so every reader sees the clock time that was picked.
  const labelOf = useMemo(() => {
    const format = new Intl.DateTimeFormat(locale, { hour: "numeric", minute: "2-digit", timeZone: "UTC" });
    return (time: string) => format.format(new Date(Date.UTC(1970, 0, 1, 0, toMinutes(time))));
  }, [locale]);
  const options = useMemo(() => {
    const slots: TimeOption[] = [];
    for (let minutes = 0; minutes < DAY_MINUTES; minutes += step) slots.push({ value: toTime(minutes), label: labelOf(toTime(minutes)) });
    return slots;
  }, [labelOf, step]);
  const endOptions = useMemo(() => [...options, { value: toTime(DAY_MINUTES), label: labelOf(toTime(DAY_MINUTES)) }], [options, labelOf]);

  const commit = (next: WeeklyHours) => {
    if (value === undefined) setOwnValue(next);
    onValueChange?.(next);
  };

  const copy = (from: Weekday, targets: Weekday[]) => {
    const next = { ...week };
    for (const target of targets) {
      next[target] = { enabled: week[from].enabled, ranges: week[from].ranges.map((range) => ({ ...range, id: nextId() })) };
    }
    commit(next);
  };

  return (
    <div className={cn("@container w-full max-w-2xl divide-y divide-border", className)}>
      {WEEKDAYS.map(({ key, name }) => (
        <DayRow
          key={key}
          day={key}
          name={name}
          hours={week[key]}
          options={options}
          endOptions={endOptions}
          labelOf={labelOf}
          step={step}
          reduceMotion={reduceMotion}
          onChange={(next) => commit({ ...week, [key]: next })}
          onCopy={(targets) => copy(key, targets)}
          nextId={nextId}
        />
      ))}
    </div>
  );
}
